#include <stdlib.h>
#include <stdbool.h>

typedef struct {
    int to;
    int next;
} Edge;

int head[200005];
Edge edges[800005];
int edge_cnt = 0;

void add_edge(int u, int v) {
    edges[edge_cnt].to = v;
    edges[edge_cnt].next = head[u];
    head[u] = edge_cnt++;
}

int degree[200005];
bool visited[200005];
bool is_neighbor[200005];

int comp[200005];
int comp_size;

void dfs(int u) {
    visited[u] = true;
    comp[comp_size++] = u;
    for (int e = head[u]; e != -1; e = edges[e].next) {
        int v = edges[e].to;
        if (!visited[v]) {
            dfs(v);
        }
    }
}

int main() {
    int n, m;
    if (scanf("%d %d", &n, &m) != 2) return 0;

    for (int i = 1; i <= n; i++) {
        head[i] = -1;
        degree[i] = 0;
        visited[i] = false;
        is_neighbor[i] = false;
    }

    for (int i = 0; i < m; i++) {
        int u, v;
        scanf("%d %d", &u, &v);
        add_edge(u, v);
        add_edge(v, u);
        degree[u]++;
        degree[v]++;
    }

    for (int i = 1; i <= n; i++) {
        if (!visited[i]) {
            comp_size = 0;
            dfs(i);

            long long edges_in_comp = 0;
            for (int j = 0; j < comp_size; j++) {
                edges_in_comp += degree[comp[j]];
            }
            edges_in_comp /= 2;

            long long max_edges = (long long)comp_size * (comp_size - 1) / 2;
            if (edges_in_comp < max_edges) {
                int r = -1;
                for (int j = 0; j < comp_size; j++) {
                    int u = comp[j];
                    if (degree[u] < comp_size - 1) {
                        r = u;
                        break;
                    }
                }

                is_neighbor[r] = true;
                for (int e = head[r]; e != -1; e = edges[e].next) {
                    is_neighbor[edges[e].to] = true;
                }

                int ans_v = -1;
                for (int j = 0; j < comp_size; j++) {
                    int u = comp[j];
                    if (!is_neighbor[u]) {
                        ans_v = u;
                        break;
                    }
                }

                printf("%d %d\n", r, ans_v);
                return 0;
            }
        }
    }

    printf("-1\n");
    return 0;
}
