#define MAXN 200005
#define MAXM 400005

int head[MAXN], to[2 * MAXM], nxt[2 * MAXM], edge_cnt;
int deg[MAXN];
int visited[MAXN];
int comp[MAXN], comp_size;
int marked[MAXN];

void add_edge(int u, int v) {
    edge_cnt++;
    to[edge_cnt] = v;
    nxt[edge_cnt] = head[u];
    head[u] = edge_cnt;
    deg[u]++;
}

int main() {
    int n, m;
    if (scanf("%d %d", &n, &m) != 2) return 0;

    for (int i = 0; i < m; i++) {
        int u, v;
        scanf("%d %d", &u, &v);
        add_edge(u, v);
        add_edge(v, u);
    }

    int *queue = (int *)malloc((n + 1) * sizeof(int));

    for (int i = 1; i <= n; i++) {
        if (!visited[i]) {
            int q_head = 0, q_tail = 0;
            queue[q_tail++] = i;
            visited[i] = 1;

            comp_size = 0;

            while (q_head < q_tail) {
                int u = queue[q_head++];
                comp[comp_size++] = u;

                for (int e = head[u]; e; e = nxt[e]) {
                    int v = to[e];
                    if (!visited[v]) {
                        visited[v] = 1;
                        queue[q_tail++] = v;
                    }
                }
            }

            // Find the vertex with the minimum degree in this component
            int min_u = comp[0];
            for (int j = 1; j < comp_size; j++) {
                if (deg[comp[j]] < deg[min_u]) {
                    min_u = comp[j];
                }
            }

            if (deg[min_u] < comp_size - 1) {
                // There is at least one vertex in the component not connected to min_u
                marked[min_u] = 1;
                for (int e = head[min_u]; e; e = nxt[e]) {
                    marked[to[e]] = 1;
                }

                int found_v = -1;
                for (int j = 0; j < comp_size; j++) {
                    if (!marked[comp[j]]) {
                        found_v = comp[j];
                        break;
                    }
                }

                printf("%d %d\n", min_u, found_v);
                free(queue);
                return 0;
            }
        }
    }

    printf("-1\n");
    free(queue);
    return 0;
}
